CREATE OR REPLACE FUNCTION public.guard_daily_pay_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb; b jsonb;
begin
 if tg_op<>'INSERT' and old.details like 'daily_work_summary:%' then a:=substring(old.details from 20)::jsonb;end if;
 if tg_op<>'DELETE' and new.details like 'daily_work_summary:%' then b:=substring(new.details from 20)::jsonb;end if;
 if a is null and b is null then return coalesce(new,old);end if;
 -- Only INSERT needs date-creation serialization. UPDATE already owns a row
 -- lock; acquiring the global lock there would invert the RPC lock order.
 if tg_op='INSERT' then perform pg_advisory_xact_lock(7140914);end if;
 if current_user in ('authenticated','anon') then
  if tg_op='DELETE' or (a is not null and (b is null or new.assignee is distinct from old.assignee or new.title is distinct from old.title)) then raise exception 'time_log_protected';end if;
  if a is not null and a->>'date' is distinct from b->>'date' then raise exception 'time_log_protected';end if;
  if jsonb_build_array(a->>'checkInAt',a->>'checkOutAt',a->>'pauseStartedAt',coalesce(a->>'pausedMilliseconds','0'),a->>'paidAt')
     is distinct from jsonb_build_array(b->>'checkInAt',b->>'checkOutAt',b->>'pauseStartedAt',coalesce(b->>'pausedMilliseconds','0'),b->>'paidAt') then raise exception 'use_attendance_payroll_actions';end if;
 elsif a->>'paidAt' is distinct from b->>'paidAt' then
  -- A privileged helper is not itself payment authority. Verify the real user.
  if private.carlos_payroll_actor() is distinct from 'owner' then raise exception 'owner_only' using errcode='42501';end if;
 end if;
 if tg_op='INSERT' and exists(select 1 from public.manager_goals g where g.assignee=new.assignee and g.title=new.title and g.details like 'daily_work_summary:%') then raise exception 'duplicate_work_date';end if;
 return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION public.log_manager_staff_record_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  source_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  destination text;
  label text;
begin
  if actor_id is null or not exists (
    select 1 from public.profiles
    where id = actor_id
      and role in ('admin', 'staff')
      and approval_status = 'approved'
      and is_active = true
  ) then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_table_name = 'manager_goals' and source_row ->> 'title' = 'Employee activity' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  destination := case tg_table_name
    when 'manager_goals' then '/admin/goals-progress'
    when 'manager_outreach_leads' then '/admin/users'
    when 'quote_requests' then '/owner/materials/requests/' || coalesce(source_row ->> 'id', '')
    when 'quote_comparisons' then '/admin/quote-comparison/' || coalesce(source_row ->> 'id', '')
    when 'supplier_quotes' then '/admin/supplier-quotes/' || coalesce(source_row ->> 'id', '')
    when 'workflow_manager_settings' then '/admin/vendors'
    else '/admin/build-map'
  end;
  label := left(coalesce(
    nullif(source_row ->> 'title', ''),
    nullif(source_row ->> 'full_name', ''),
    nullif(source_row ->> 'supplier_name', ''),
    replace(initcap(tg_table_name), '_', ' ')
  ), 160);

  insert into public.manager_staff_activity_events (
    user_id, event_type, page_path, page_label, entity_type, entity_id, metadata
  ) values (
    actor_id,
    case tg_op when 'INSERT' then 'record_created' when 'DELETE' then 'record_deleted' else 'record_updated' end,
    destination,
    replace(initcap(tg_table_name), '_', ' '),
    tg_table_name,
    source_row ->> 'id',
    jsonb_build_object('label', label)
  );
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_manager_goals_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
